import { test, expect } from '@playwright/test';

test.describe('Navigation Menu Active Item Highlighting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/navigation');
  });

  test('should highlight the active menu item when navigating to a page', async ({ page }) => {
    // Verify navigation bar is visible
    const navBar = page.getByRole('navigation');
    await expect(navBar).toBeVisible();

    // Verify initial active state (Home should be highlighted)
    const homeLink = page.getByRole('link', { name: 'Home' });
    await expect(homeLink).toHaveClass(/active-menu-item/);

    // Verify other links are not highlighted
    const aboutLink = page.getByRole('link', { name: 'About' });
    await expect(aboutLink).not.toHaveClass(/active-menu-item/);

    // Click on About link
    await aboutLink.click();

    // Wait for navigation to complete
    await page.waitForURL(/.*\/about/);

    // Verify About link is now highlighted
    await expect(aboutLink).toHaveClass(/active-menu-item/);

    // Verify Home link is no longer highlighted
    await expect(homeLink).not.toHaveClass(/active-menu-item/);

    // Verify page content reflects About section
    const aboutContent = page.getByText('About Us');
    await expect(aboutContent).toBeVisible();
  });

  test('should remove highlight when navigating back to a previously active page', async ({ page }) => {
    // Navigate to About page first
    const aboutLink = page.getByRole('link', { name: 'About' });
    await aboutLink.click();
    await page.waitForURL(/.*\/about/);

    // Verify About link is highlighted
    await expect(aboutLink).toHaveClass(/active-menu-item/);

    // Navigate to Contact page
    const contactLink = page.getByRole('link', { name: 'Contact' });
    await contactLink.click();
    await page.waitForURL(/.*\/contact/);

    // Verify Contact link is highlighted
    await expect(contactLink).toHaveClass(/active-menu-item/);

    // Verify About link is no longer highlighted
    await expect(aboutLink).not.toHaveClass(/active-menu-item/);

    // Navigate back to About page
    await aboutLink.click();
    await page.waitForURL(/.*\/about/);

    // Verify About link is highlighted again
    await expect(aboutLink).toHaveClass(/active-menu-item/);

    // Verify Contact link is no longer highlighted
    await expect(contactLink).not.toHaveClass(/active-menu-item/);

    // Verify page content reflects About section
    const aboutContent = page.getByText('About Us');
    await expect(aboutContent).toBeVisible();
  });
});
